// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Process liveness
	// (GET /healthz)
	GetLiveness(ctx context.Context, request GetLivenessRequestObject) (GetLivenessResponseObject, error)
	// Dependency readiness
	// (GET /readyz)
	GetReadiness(ctx context.Context, request GetReadinessRequestObject) (GetReadinessResponseObject, error)
	// Progress of an adoption or forget job
	// (GET /v1/admin/adoptions/{jobId})
	GetAdoptionJob(ctx context.Context, request GetAdoptionJobRequestObject) (GetAdoptionJobResponseObject, error)
	// This control room's identity and provisioning defaults
	// (GET /v1/admin/control-room)
	GetControlRoom(ctx context.Context, request GetControlRoomRequestObject) (GetControlRoomResponseObject, error)
	// The fleet view — known devices joined with what mDNS sees on the LAN
	// (GET /v1/admin/devices)
	ListDevices(ctx context.Context, request ListDevicesRequestObject) (ListDevicesResponseObject, error)
	// One device with its desired config and recent sessions
	// (GET /v1/admin/devices/{deviceId})
	GetDevice(ctx context.Context, request GetDeviceRequestObject) (GetDeviceResponseObject, error)
	// Rename a device
	// (PATCH /v1/admin/devices/{deviceId})
	UpdateDevice(ctx context.Context, request UpdateDeviceRequestObject) (UpdateDeviceResponseObject, error)
	// Adopt a device over the network (discovered, or by IP)
	// (POST /v1/admin/devices/{deviceId}/adopt)
	AdoptDevice(ctx context.Context, request AdoptDeviceRequestObject) (AdoptDeviceResponseObject, error)
	// Clear the desired config
	// (DELETE /v1/admin/devices/{deviceId}/desired-config)
	ClearDesiredConfig(ctx context.Context, request ClearDesiredConfigRequestObject) (ClearDesiredConfigResponseObject, error)
	// Set the desired sebastian.config.v1 for a device
	// (PUT /v1/admin/devices/{deviceId}/desired-config)
	SetDesiredConfig(ctx context.Context, request SetDesiredConfigRequestObject) (SetDesiredConfigResponseObject, error)
	// Set (or clear) the desired device profile
	// (PUT /v1/admin/devices/{deviceId}/desired-profile)
	SetDesiredProfile(ctx context.Context, request SetDesiredProfileRequestObject) (SetDesiredProfileResponseObject, error)
	// Return a device to factory (unadopted) and drop it from the inventory
	// (POST /v1/admin/devices/{deviceId}/forget)
	ForgetDevice(ctx context.Context, request ForgetDeviceRequestObject) (ForgetDeviceResponseObject, error)
	// Ask the unit to record a meeting (RM-03)
	// (POST /v1/admin/devices/{deviceId}/meetings)
	StartMeeting(ctx context.Context, request StartMeetingRequestObject) (StartMeetingResponseObject, error)
	// Issue a new per-device secret (shown once)
	// (POST /v1/admin/devices/{deviceId}/secret)
	RegenerateDeviceSecret(ctx context.Context, request RegenerateDeviceSecretRequestObject) (RegenerateDeviceSecretResponseObject, error)
	// Meetings, newest first (RM-40)
	// (GET /v1/admin/meetings)
	ListMeetings(ctx context.Context, request ListMeetingsRequestObject) (ListMeetingsResponseObject, error)
	// Delete audio and content irreversibly, keeping the trace (RM-46)
	// (DELETE /v1/admin/meetings/{meetingId})
	DeleteMeeting(ctx context.Context, request DeleteMeetingRequestObject) (DeleteMeetingResponseObject, error)
	// One meeting (RM-41)
	// (GET /v1/admin/meetings/{meetingId})
	GetMeeting(ctx context.Context, request GetMeetingRequestObject) (GetMeetingResponseObject, error)
	// Rename speakers and flag the meeting to keep (RM-31, RM-45)
	// (PATCH /v1/admin/meetings/{meetingId})
	UpdateMeeting(ctx context.Context, request UpdateMeetingRequestObject) (UpdateMeetingResponseObject, error)
	// Stop a meeting (RM-22; the agent uses it for RM-21)
	// (POST /v1/admin/meetings/{meetingId}/stop)
	StopMeeting(ctx context.Context, request StopMeetingRequestObject) (StopMeetingResponseObject, error)
	// Generate the summary again (RM-32)
	// (POST /v1/admin/meetings/{meetingId}/summarize)
	SummarizeMeeting(ctx context.Context, request SummarizeMeetingRequestObject) (SummarizeMeetingResponseObject, error)
	// Transcribe again (RM-33)
	// (POST /v1/admin/meetings/{meetingId}/transcribe)
	TranscribeMeeting(ctx context.Context, request TranscribeMeetingRequestObject) (TranscribeMeetingResponseObject, error)
	// The transcript as a download, txt or srt (RM-41)
	// (GET /v1/admin/meetings/{meetingId}/transcript)
	GetMeetingTranscript(ctx context.Context, request GetMeetingTranscriptRequestObject) (GetMeetingTranscriptResponseObject, error)
	// List recent voice recordings
	// (GET /v1/admin/recordings)
	ListRecordings(ctx context.Context, request ListRecordingsRequestObject) (ListRecordingsResponseObject, error)
	// Register a recording already stored in object storage
	// (POST /v1/admin/recordings)
	RegisterRecording(ctx context.Context, request RegisterRecordingRequestObject) (RegisterRecordingResponseObject, error)
	// Aggregate recording storage and duration metrics
	// (GET /v1/admin/recordings/summary)
	GetRecordingsSummary(ctx context.Context, request GetRecordingsSummaryRequestObject) (GetRecordingsSummaryResponseObject, error)
	// Get one voice recording
	// (GET /v1/admin/recordings/{recordingId})
	GetRecording(ctx context.Context, request GetRecordingRequestObject) (GetRecordingResponseObject, error)
	// The desired sebastian.config.v1 document for this device
	// (GET /v1/devices/{deviceId}/config)
	GetDeviceConfig(ctx context.Context, request GetDeviceConfigRequestObject) (GetDeviceConfigResponseObject, error)
	// Desired device profile for reconciliation polls
	// (GET /v1/devices/{deviceId}/desired-profile)
	GetDesiredProfile(ctx context.Context, request GetDesiredProfileRequestObject) (GetDesiredProfileResponseObject, error)
	// Challenge for a device to enrol with the organization secret
	// (GET /v1/devices/{deviceId}/enroll)
	GetEnrollmentChallenge(ctx context.Context, request GetEnrollmentChallengeRequestObject) (GetEnrollmentChallengeResponseObject, error)
	// Enrol a device that proves it holds the organization secret
	// (POST /v1/devices/{deviceId}/enroll)
	EnrollDevice(ctx context.Context, request EnrollDeviceRequestObject) (EnrollDeviceResponseObject, error)
	// The unit confirms it records, or that it stopped and why (RM-52)
	// (PUT /v1/devices/{deviceId}/meeting)
	ReportMeeting(ctx context.Context, request ReportMeetingRequestObject) (ReportMeetingResponseObject, error)
	// The unit asks for a meeting after the MUTE gesture (RM-02)
	// (POST /v1/devices/{deviceId}/meetings)
	RequestMeeting(ctx context.Context, request RequestMeetingRequestObject) (RequestMeetingResponseObject, error)
	// The device reports the configuration it runs (RF-42)
	// (PUT /v1/devices/{deviceId}/running-config)
	ReportRunningConfig(ctx context.Context, request ReportRunningConfigRequestObject) (ReportRunningConfigResponseObject, error)
	// Create a device session and dispatch its assigned agent
	// (POST /v1/sessions)
	CreateSession(ctx context.Context, request CreateSessionRequestObject) (CreateSessionResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// GetLiveness operation middleware
func (sh *strictHandler) GetLiveness(w http.ResponseWriter, r *http.Request) {
	var request GetLivenessRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.GetLiveness(ctx, request.(GetLivenessRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "GetLiveness")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(GetLivenessResponseObject); ok {
		if err := validResponse.VisitGetLivenessResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

